package com.schoolapp.core.data.academics

import com.schoolapp.core.common.result.AppResult
import com.schoolapp.core.model.academics.CatalogueSubject
import com.schoolapp.core.model.academics.Room

/** School subjects and branch rooms (master lists). The API has no delete for either; they are renamed. */
interface CatalogueRepository {
    suspend fun subjects(schoolId: String?): AppResult<List<CatalogueSubject>>

    /** Code is generated by the server; [classIds] also links it to those classes (appended last). */
    suspend fun createSubject(schoolId: String, name: String, classIds: List<String> = emptyList(), periodsPerWeek: Int? = null): AppResult<CatalogueSubject>
    suspend fun renameSubject(subjectId: String, name: String): AppResult<CatalogueSubject>
    suspend fun rooms(branchId: String): AppResult<List<Room>>

    /** 409 ROOM_NAME_TAKEN. */
    suspend fun createRoom(branchId: String, name: String, capacity: Int? = null): AppResult<Room>
    suspend fun updateRoom(roomId: String, name: String, capacity: Int?): AppResult<Room>
}
